function lookupDerivadosCoeffs(
  key: number,
  table: DerivadosCoeffsRow[],
): [number, number, number, number] {
  if (table.length === 0) return [0, 0, 0, 0];
  if (key < table[0].damb) {
    const row = table[0];
    return [row.p1, row.p2, row.p3, row.p4];
  }
  for (let i = table.length - 1; i >= 0; i--) {
    if (key >= table[i].damb) {
      const row = table[i];
      return [row.p1, row.p2, row.p3, row.p4];
    }
  }
  const row = table[0];
  return [row.p1, row.p2, row.p3, row.p4];
}

export function density20FromAmbient(
  densityAmbient: number,
  temperature: number,
): number {
  const rhoG = densityAmbient / 1000;
  const dt = temperature - 20;
  const [p1, p2, p3, p4] = lookupDerivadosCoeffs(densityAmbient, dns20Table);
  const numerator = rhoG - p1 * dt - p3 * dt * dt;
  const denominator = 1 + p2 * dt + p4 * dt * dt;
  const hyc = 1 - 0.000023 * dt - 0.00000002 * dt * dt;
  return (numerator / denominator) * hyc * 1000;
}

export function ctlFromDensity20(
  density20: number,
  temperatureCt: number,
): number {
  const dt = temperatureCt - 20;
  const [p1, p2, p3, p4] = lookupDerivadosCoeffs(density20, fcv20Table);
  const rho20G = density20 / 1000;
  return (
    1 +
    p2 * dt +
    p4 * dt * dt +
    (p1 * dt + p3 * dt * dt) / rho20G
  );
}
